# deliver-33-edit-add-items.ps1
# Auto-writes files and git add/commit/push, then self-deletes
$ErrorActionPreference = "Stop"
$utf8NoBom = New-Object System.Text.UTF8Encoding($false)

function Decode-Base64Text($b64text) {
    $bytes = [System.Convert]::FromBase64String($b64text)
    return [System.Text.Encoding]::UTF8.GetString($bytes)
}

function Write-Base64File($path, $b64text, $label) {
    $text = Decode-Base64Text $b64text
    $dir = Split-Path $path -Parent
    if ($dir -and -not (Test-Path $dir)) {
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
    }
    [System.IO.File]::WriteAllText($path, $text, $utf8NoBom)
    Write-Host "$label$path"
}

$ProjectRoot = Get-Location
$SrcDir = Join-Path $ProjectRoot "src"

$install_installer_b64 = "ZGVsaXZlci0zMy1lZGl0LWFkZC1pdGVtcy5wczE="
$write_prefix_b64 = "5a+r5YWlOiA="
$start_write_b64 = "PT09IOmWi+Wni+Wvq+WFpeaqlOahiCA9PT0="
$start_git_b64 = "PT09IOmWi+WniyBnaXQg5pON5L2cID09PQ=="
$done_pushed_b64 = "PT09IOWujOaIkO+8geW3sue2kyBjb21taXQg5LimIHB1c2gg5LqGID09PQ=="
$no_changes_b64 = "PT09IOaykuacieWBtea4rOWIsOiuiuabtO+8jOeVpemBjiBjb21taXQgPT09"
$self_delete_b64 = "6YCZ5YCL5a6J6KOd6IWz5pys5Y2z5bCH6Ieq5YuV5Yiq6ZmkLi4u"

Write-Host (Decode-Base64Text $start_write_b64)


$pages_OrderForm_jsx_b64 = ""
Write-Base64File (Join-Path $SrcDir "pages\OrderForm.jsx") $pages_OrderForm_jsx_b64 (Decode-Base64Text $write_prefix_b64)

$pages_CustomerPanel_jsx_b64 = ""
Write-Base64File (Join-Path $SrcDir "pages\CustomerPanel.jsx") $pages_CustomerPanel_jsx_b64 (Decode-Base64Text $write_prefix_b64)

Write-Host ""
Write-Host (Decode-Base64Text $start_git_b64)
Set-Location $ProjectRoot

git add -A

$msgFile = Join-Path $env:TEMP "commit_msg_$(Get-Random).txt"

$commitMsg_b64 = "57eo6Lyv5Zau562G6IiK5raI6LK757SA6YyE5pmC5Y+v5Lul5YaN5Yqg55Si5ZOB77yI5a2Y5qqU5b6M6K6K5oiQ5LiA5by16KiC5Zau77yJ"

$msgText = Decode-Base64Text $commitMsg_b64
[System.IO.File]::WriteAllText($msgFile, $msgText, $utf8NoBom)

$hasChanges = git status --porcelain
if ($hasChanges) {
    git commit -F $msgFile
    git push
    Write-Host ""
    Write-Host (Decode-Base64Text $done_pushed_b64)
} else {
    Write-Host ""
    Write-Host (Decode-Base64Text $no_changes_b64)
}

Remove-Item $msgFile -Force -ErrorAction SilentlyContinue

Write-Host ""
Write-Host (Decode-Base64Text $self_delete_b64)
Start-Sleep -Seconds 1
Remove-Item -Path $PSCommandPath -Force
